import sys

def main():
    data = sys.stdin.read().split()
    a, b, c, h, l = map(int, data[:5])
    dims = [a, b, c]
    ok = False
    for i in range(3):
        for j in range(i + 1, 3):
            x, y = dims[i], dims[j]
            if (x <= h and y <= l) or (x <= l and y <= h):
                ok = True
                break
        if ok:
            break
    print('S' if ok else 'N')

main()
